const {chromium}=require('playwright'), fs=require('node:fs');
const host='https://chelovek-neiroset.ru',slug='/ai-kreativy-dlya-biznesa/',url=host+slug;
const title='AI-креативы для бизнеса и рекламы | Vikey AI',description='Создаю AI-креативы и визуальный контент для бизнеса: изображения для рекламы, сайтов, соцсетей, презентаций и проектов под конкретную задачу.';
const routes=['/','/privacy','/sayty-dlya-biznesa/','/ii-assistent-dlya-biznesa/','/telegram-boty-dlya-biznesa/','/avtomatizaciya-biznesa-ai/','/ai-video-dlya-biznesa/','/upakovka-proekta/','/case-sayt-gostevye-domiki/','/case-b2b-horeca/','/case-ai-telegram-bot/','/case-cifrovoy-avatar/','/case-sayt-chastnogo-specialista/','/case-sayt-lichnogo-brenda/',slug];
const report={date:new Date().toISOString(),checks:{},devices:{},regressions:[],errors:[]};
const set=(n,ok,data={})=>report.checks[n]={pass:!!ok,...data};
const safe=async(n,fn)=>{try{await fn()}catch(e){report.errors.push(n+': '+String(e.message||e));set(n,false,{error:String(e.message||e)})}};
async function run(){
 const browser=await chromium.launch({headless:true,args:['--no-sandbox']});
 try{
  const context=await browser.newContext({viewport:{width:1440,height:900}});
  try{
   await safe('HTTP',async()=>{const r=await context.request.get(url,{maxRedirects:0,timeout:35000});set('HTTP',r.status()===200,{status:r.status()})});
   await safe('Redirect',async()=>{const r=await context.request.get(host+'/ai-kreativy-dlya-biznesa',{maxRedirects:0,timeout:35000});const location=r.headers()['location']||'';set('Redirect',[301,302,307,308].includes(r.status())&&(location===slug||location===url),{status:r.status(),location})});
   await safe('Sitemap',async()=>{const r=await context.request.get(host+'/sitemap.xml',{timeout:35000});const xml=await r.text();const a=[...xml.matchAll(/<loc>\s*([^<]+)\s*<\/loc>/g)].map(m=>m[1].trim());set('Sitemap',r.status()===200&&a.length===15&&a.includes(url),{status:r.status(),count:a.length,hasUrl:a.includes(url)})});
   for(const [n,path,link] of [['Home to creatives','/',slug],['Creatives to video',slug,'/ai-video-dlya-biznesa/'],['Video to creatives','/ai-video-dlya-biznesa/',slug],['Creatives to sites',slug,'/sayty-dlya-biznesa/']])await safe(n,async()=>{const p=await context.newPage();try{const r=await p.goto(host+path,{waitUntil:'domcontentloaded',timeout:40000});const count=await p.locator('a').evaluateAll((els,href)=>els.filter(x=>x.getAttribute('href')===href).length,link);set(n,r.status()===200&&count>0,{status:r.status(),links:count})}finally{await p.close()}});
   await safe('SEO',async()=>{const p=await context.newPage();try{const r=await p.goto(url,{waitUntil:'domcontentloaded',timeout:40000});const d=await p.evaluate(()=>({title:document.title,description:document.querySelector('meta[name="description"]')?.content||'',robots:document.querySelector('meta[name="robots"]')?.content||'',canonical:document.querySelector('link[rel="canonical"]')?.href||'',og:document.querySelector('meta[property="og:url"]')?.content||'',h1:[...document.querySelectorAll('h1')].map(x=>x.textContent.trim().replace(/\s+/g,' ')),faq:document.querySelectorAll('details').length,cta:!!document.querySelector('a[href="/#calc"]'),manifest:!!document.querySelector('link[rel="manifest"]')}));set('SEO',r.status()===200);for(const [key,val,want] of [['Title',d.title,title],['Description',d.description,description],['Robots',d.robots,'index,follow'],['Canonical',d.canonical,url],['og:url',d.og,url]])set(key,val===want,{actual:val});set('H1',d.h1.length===1&&d.h1[0]==='Создание AI-креативов для бизнеса',{actual:d.h1});set('FAQ',d.faq===6,{count:d.faq});set('CTA',d.cta);set('No PWA manifest',!d.manifest)}finally{await p.close()}});
   for(const route of routes)await safe('Regression '+route,async()=>{const r=await context.request.get(host+route,{timeout:35000});report.regressions.push({route,status:r.status(),pass:r.status()===200});set('Regression '+route,r.status()===200,{status:r.status()})});
  }finally{await context.close()}
  for(const [name,w,h] of [['iPhone',390,844],['Android',412,915],['Desktop',1440,900]])await safe('Device '+name,async()=>{const ctx=await browser.newContext({viewport:{width:w,height:h},isMobile:name!=='Desktop',hasTouch:name!=='Desktop',deviceScaleFactor:name==='Desktop'?1:3});const p=await ctx.newPage();try{
    await p.addInitScript(()=>{window.__cls=0;try{new PerformanceObserver(l=>{for(const e of l.getEntries())if(!e.hadRecentInput)window.__cls+=e.value}).observe({type:'layout-shift',buffered:true})}catch(e){}});
    const r=await p.goto(url,{waitUntil:'domcontentloaded',timeout:40000});await p.waitForTimeout(1600);const d=await p.evaluate(async()=>({overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+1,cls:window.__cls||0,h1:document.querySelectorAll('h1').length,faq:document.querySelectorAll('details').length,cta:!!document.querySelector('a[href="/#calc"]'),footer:!!document.querySelector('footer'),images:[...document.querySelectorAll('main img')].every(x=>x.complete&&x.naturalWidth>0),sw:'serviceWorker' in navigator?(await navigator.serviceWorker.getRegistrations()).length:0}));
    const home=await p.goto(host+'/',{waitUntil:'domcontentloaded',timeout:40000});await p.waitForTimeout(1000);const homeData=await p.evaluate(()=>{const cards=document.querySelectorAll('#services h3');return {count:cards.length,overflow:document.documentElement.scrollWidth>document.documentElement.clientWidth+1,hasLink:!!document.querySelector('a[href="/ai-kreativy-dlya-biznesa/"]')}});
    const refreshed=await p.goto(url,{waitUntil:'domcontentloaded',timeout:40000});const again=await p.reload({waitUntil:'domcontentloaded',timeout:40000});
    const ok=r.status()===200&&refreshed.status()===200&&again.status()===200&&!d.overflow&&d.cls<=0.1&&d.h1===1&&d.faq===6&&d.cta&&d.footer&&d.images&&d.sw===0&&home.status()===200&&!homeData.overflow&&homeData.hasLink&&homeData.count===7;
    report.devices[name]={pass:ok,status:r.status(),refresh:again.status(),width:w,height:h,...d,home:homeData};set('Device '+name,ok,report.devices[name]);
  }finally{await ctx.close()}});
 }finally{await browser.close()}
}
(async()=>{try{await run()}catch(e){report.errors.push('fatal: '+String(e.stack||e))}finally{report.passed=Object.values(report.checks).length>=35&&Object.values(report.checks).every(c=>c.pass)&&report.regressions.length===routes.length&&Object.keys(report.devices).length===3&&report.errors.length===0;fs.writeFileSync('.github/vikey-creatives-live-report-temp.json',JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify({passed:report.passed,failed:Object.entries(report.checks).filter(([k,v])=>!v.pass).map(([k])=>k),errors:report.errors}));process.exitCode=report.passed?0:1}})();